  \end{subfigure}

  \caption{Единицы СИ (выделены) жирные в \texlive 2021, но не в \texlive 2020 (arXiv:2306.00001~<<CMD_142>>)}
  <<CMD_273>>
\end{figure}

\paragraph{Ожидаемое поведение}

